import {species} from './catalogue.js';
import {aliases} from './guide.js';
import {summariseWeather, habitatAdvice, candidateList, scoutingTaxon, localDate, dateAgo} from './engine.js';
const canonical = name => aliases[name] || name;
const $ = id => document.getElementById(id);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL = u => {try {const url=new URL(u);return url.protocol==='https:'?url.href:'';}catch{return '';}};
const number = n => typeof n==='number' && Number.isFinite(n);
const sum = arr => arr.reduce((a,b)=>a+b,0);
let state={location:{name:'Guildford area, Surrey',lat:51.2362,lng:-0.5704},weather:null,observations:null,recent:null,recentAt:null,recentCoverage:null,observationsAt:null,weatherAt:null,month:new Date().getMonth()+1,offline:false,coverage:null};
let photos={},busy=false,sequence=0,installPrompt=null,visibleLimit=12;
try {photos=JSON.parse(localStorage.getItem('mycelium-photos-v1')||'{}');}catch{}
try {const previous=JSON.parse(localStorage.getItem('mycelium-report-v4')||'null');if(previous?.location&&number(previous.location.lat)&&number(previous.location.lng)&&previous.month===state.month){state={...state,...previous,offline:true};}}catch{}
async function json(url){const r=await fetch(url,{signal:AbortSignal.timeout(18000)});if(!r.ok)throw new Error(`Source returned ${r.status}`);return r.json();}
function save(){try{localStorage.setItem('mycelium-report-v4',JSON.stringify(state));localStorage.setItem('mycelium-photos-v1',JSON.stringify(photos));}catch{}}
const fmt=(n,unit='',digits=1)=>number(n)?`${n.toFixed(digits)}${unit}`:'Unavailable';
const stamp=t=>t?new Date(t).toLocaleString('en-GB',{timeZone:'Europe/London',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'Unavailable';
const clock=t=>new Date(t*1000).toLocaleTimeString('en-GB',{timeZone:'Europe/London',hour:'2-digit',minute:'2-digit'});
function weatherSummary(){return state.weather;}
function candidates(){return candidateList(species,state.recent,state.observations,state.month);}
function selectedCandidates(){const habitat=$('habitat').value,view=$('view').value,search=$('species-search').value.trim().toLowerCase();return candidates().filter(s=>(habitat==='all'||s.habitat===habitat)&&(!search||`${s.name} ${s.latin} ${s.searchNames||''}`.toLowerCase().includes(search))&&(view==='all'||view==='local'&&(s.recent||s.seasonal)||view==='seasonal'&&(s.recent||s.seasonal||s.inSeason)));}
function evidence(s){return s.recent?(state.recentCoverage?.to===localDate(Date.now()/1000)?'Recorded in last 14 days':'Recent records · saved'):s.seasonal?'Historical seasonal record':s.inSeason?'UK seasonal guide':'Other-season guide';}
function imageMarkup(s){const p=photos[s.latin];return p?.url?`<img src="${esc(safeURL(p.url))}" alt="Reference photograph of ${esc(s.name)}" loading="lazy" data-photo="${s.id}">`:'<span class="photo-missing">Reference photo requires an online connection</span>';}
function attachImageErrors(root){root.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{const span=document.createElement('span');span.className='photo-missing';span.textContent='Photo could not load';img.replaceWith(span);},{once:true}));}
function render(){
 const l=state.location,w=weatherSummary(),old=w&&Date.now()/1000-w.cutoff>21600;
 $('location-name').textContent=l.name;$('coordinates').textContent=`${l.lat.toFixed(3)}, ${l.lng.toFixed(3)} · 30 km records radius`;
 $('report-date').textContent=w?`${localDate(w.cutoff)} · ${old?'Saved report':'Conditions as of'} ${clock(w.cutoff)}`:'Your woodland report';
 $('outlook').textContent=w?w.title:'Find the right habitat first';
 $('outlook-detail').textContent=w?`${fmt(w.rain7,' mm')} rain over the past 7 days, including today so far. ${w.delta===null?'Soil trend unavailable.':Math.abs(w.delta)<0.005?'Topsoil moisture is broadly steady over 3 days.':w.delta>0?'Topsoil moisture has risen over 3 days.':'Topsoil moisture has fallen over 3 days.'} ${w.balance!==null?`Rain minus reference evaporation: ${w.balance.toFixed(1)} mm this week.`:''}`:'Refresh online for current moisture, today’s rain and a daily scouting guide. The UK habitat guide remains available.';
 $('score').textContent=w?.score===null||!w?'—':w.score;
 $('score-note').textContent=!w?'Waiting for weather':w.score===null?'Incomplete data · no score':'Conditions index / 100';
 $('rain').textContent=w?fmt(w.rainToday,' mm'):'—';$('rain-context').textContent=w?`Today to ${clock(w.hourThrough)} · modelled`:'Today so far';
 $('soil').textContent=w?fmt(w.soil===null?null:w.soil*100,'%'):'—';$('soil-context').textContent=w?`3–9 cm · ${w.delta===null?'trend unavailable':`${w.delta>=0?'+':''}${(w.delta*100).toFixed(1)} percentage points / 3 days`}`:'Modelled water content';
 $('deep-soil').textContent=w?fmt(w.deepSoil===null?null:w.deepSoil*100,'%'):'—';$('deep-context').textContent=w?`9–27 cm · soil ${fmt(w.soilTemp,' °C')}`:'Modelled water content';
 $('temp').textContent=w?fmt(w.overnight,' °C'):'—';$('night-context').textContent=w?`18:00–08:00${w.nightComplete?'':' · night so far'}`:'Overnight minimum';
 $('weather-extra').textContent=w?`Rain over 28 days: ${fmt(w.rain28,' mm')}. Wet days in the last week: ${fmt(w.wetDays,'',0)}. Mean humidity over 24 hours: ${fmt(w.rh24,'%')}. Mean wind: ${fmt(w.wind24,' km/h')}. Seven-day reference evaporation: ${fmt(w.et7,' mm')}. The index is calculated from ${w.parts?w.parts.map(p=>`${p.label}: ${Math.round(p.points)}/${p.max}`).join('; ')+`; penalties: ${w.penalty}.`:'incomplete inputs, so no score is shown.'}`:'Extended weather unavailable.';
 $('updated').textContent=`Weather: ${stamp(state.weatherAt)}${old?' · stale, refresh before heading out':''}. Model estimates; woodland ground may differ.`;
 $('route-heading').textContent=w&&localDate(w.cutoff)!==localDate(Date.now()/1000)?`Where to look · saved report ${localDate(w.cutoff)}`:'Where to look today';
 $('route-list').innerHTML=habitatAdvice(w).map((x,i)=>`<article><span class="route-number">0${i+1}</span><div><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p></div></article>`).join('');
 const all=selectedCandidates(),list=all.slice(0,visibleLimit);
 $('evidence-note').textContent=`Recent sightings (${state.recentCoverage?state.recentCoverage.from+' to '+state.recentCoverage.to:'unavailable'}): ${stamp(state.recentAt)}. Seasonal records: ${stamp(state.observationsAt)}. Recent = last 14 days; seasonal = this month across all years. Neither confirms a flush in your wood.${state.coverage?.truncated||state.recentCoverage?.truncated?' Provider cap reached; results incomplete.':''}`;
 $('results-count').textContent=`${all.length} matching species · showing ${list.length} · ${species.length} guide entries plus nearby species`;
 $('species-grid').innerHTML=list.map(s=>`<article class="species-card"><div class="photo-wrap">${imageMarkup(s)}</div><div class="card-body"><span class="signal ${s.recent?'recent':''}">${evidence(s)}</span><h3>${esc(s.name)}</h3><span class="scientific">${esc(s.latin)}</span><p>${esc(s.where)}</p><div class="card-foot"><span>${s.recent?`${s.recent.count} recent record${s.recent.count===1?'':'s'}`:s.seasonal?`${s.seasonal.count} historical records`:'Local presence unverified'}</span><button data-details="${esc(s.id)}">Details ↗</button></div></div></article>`).join('');
 $('empty').hidden=!!list.length;$('show-more').hidden=all.length<=visibleLimit;attachImageErrors($('species-grid'));
}
function showDetails(id){const s=candidates().find(s=>s.id===id);if(!s)return;const p=photos[s.latin];
 const query=new URLSearchParams({taxon_name:s.latin,lat:state.location.lat,lng:state.location.lng,radius:30,quality_grade:'research'});
 if(s.recent){query.set('d1',state.recentCoverage.from);query.set('d2',state.recentCoverage.to);}else query.set('month',state.month);
 $('detail-content').innerHTML=`<p class="eyebrow">${evidence(s)}</p><h2>${esc(s.name)}</h2><p><em>${esc(s.latin)}</em></p>${imageMarkup(s)}${p?`<p class="metadata">${esc(p.attribution)} · <a href="${esc(safeURL(p.photoURL))}" target="_blank" rel="noopener">Original photo</a></p>`:''}<h3>Where to look</h3><p>${esc(s.where)}</p><h3>Season and fruiting context</h3><p>${s.months.length?s.months.map(m=>new Date(2025,m-1).toLocaleString('en-GB',{month:'short'})).join(' · '):'Season not documented in this guide'}. ${esc(s.timing)}</p><p>${s.recent?`${s.recent.count} research-grade records in the last 14 days (${state.recentCoverage.from} to ${state.recentCoverage.to}). `:''}${s.seasonal?`${s.seasonal.count} records in this month across all years. `:''}Within 30 km; recording effort varies. Absence of records does not establish absence.</p><h3>Identification context</h3><p>${esc(s.description)}</p><p>${esc(s.caution)} Never eat a mushroom based on this app.</p><div class="source-links">${s.source?`<a href="https://www.first-nature.com/fungi/${esc(s.source)}.php" target="_blank" rel="noopener">Species ecology reference ↗</a>`:'<a href="https://www.first-nature.com/fungi/" target="_blank" rel="noopener">Fungi reference index ↗</a>'}<a href="https://www.inaturalist.org/observations?${esc(query)}" target="_blank" rel="noopener">Explore actual local records ↗</a></div>`;
 attachImageErrors($('detail-content'));$('detail-dialog').showModal();
}
async function weather(l){const q=new URLSearchParams({latitude:l.lat,longitude:l.lng,past_days:28,forecast_days:1,timezone:'Europe/London',timeformat:'unixtime',current:'temperature_2m,relative_humidity_2m,precipitation,soil_moisture_3_to_9cm,soil_moisture_9_to_27cm,soil_temperature_6cm',hourly:'precipitation,temperature_2m,relative_humidity_2m,wind_speed_10m,soil_moisture_3_to_9cm,soil_moisture_9_to_27cm,soil_temperature_6cm,et0_fao_evapotranspiration',daily:'precipitation_sum,temperature_2m_min,temperature_2m_max'});return summariseWeather(await json(`https://api.open-meteo.com/v1/forecast?${q}`));}
async function observations(l,recent=false){const counts={};let truncated=false,total=0,excluded=0;const now=Date.now()/1000,to=localDate(now),from=dateAgo(to,13);
 for(let page=1;page<=6;page++){
 const q=new URLSearchParams({taxon_id:47170,quality_grade:'research',lat:l.lat,lng:l.lng,radius:30,per_page:500,page,locale:'en'});
 if(recent){q.set('d1',from);q.set('d2',to);}else q.set('month',state.month);
 const data=await json(`https://api.inaturalist.org/v1/observations/species_counts?${q}`);if(!Array.isArray(data.results))throw new Error('Incomplete sightings');total=number(data.total_results)?data.total_results:total;
 for(const r of data.results){const t=r.taxon;if(!scoutingTaxon(t)){excluded++;continue;}if(!t.name||!number(t.id)||!number(r.count)||r.count<1)continue;const name=canonical(t.name),old=counts[name];counts[name]={count:(old?.count||0)+r.count,id:t.id,name:t.preferred_common_name||t.name};capturePhoto({...t,name});}
 if(data.results.length<500||total>0&&page*500>=total)break;if(page===6)truncated=true;
 }return {counts,coverage:{truncated,totalTaxa:total,excluded,from,to}};
}
function capturePhoto(t){const p=t.default_photo;if(!p?.medium_url&&!p?.url)return;const url=safeURL(p.medium_url||p.url);if(url)photos[canonical(t.name)]={url,attribution:p.attribution||'Photo via iNaturalist',photoURL:number(p.id)?`https://www.inaturalist.org/photos/${p.id}`:''};}
const photoRequests=new Set();
async function fillPhotos(){const queue=selectedCandidates().slice(0,visibleLimit).filter(s=>!photos[s.latin]&&!s.recordOnly&&!photoRequests.has(s.latin));queue.forEach(s=>photoRequests.add(s.latin));async function worker(){while(queue.length){const s=queue.shift();try{const q=new URLSearchParams({q:s.latin,per_page:5,locale:'en'});const data=await json(`https://api.inaturalist.org/v1/taxa?${q}`);const taxon=data.results?.find(t=>canonical(t.name)===s.latin);if(taxon)capturePhoto(taxon);render();save();}catch{}}}await Promise.all([worker(),worker()]);}
async function refresh(location=state.location){if(busy)return;busy=true;const token=++sequence;const changed=location.lat!==state.location.lat||location.lng!==state.location.lng;const month=Number(localDate(Date.now()/1000).slice(5,7));
 if(changed||month!==state.month)state={...state,weather:null,observations:null,recent:null,weatherAt:null,observationsAt:null,recentAt:null,coverage:null,recentCoverage:null};
 state.month=month;state.location=location;$('status').textContent='Updating moisture, recent sightings and seasonal records…';$('refresh').disabled=true;$('locate').disabled=true;render();
 const failures=[];
 async function load(key,fn,coverageKey){try{const result=await fn();if(token!==sequence)return;state[key]=coverageKey?result.counts:result;state[key==='weather'?'weatherAt':key==='recent'?'recentAt':'observationsAt']=new Date().toISOString();if(coverageKey)state[coverageKey]=result.coverage;save();render();}catch{failures.push(key==='weather'?'Weather':key==='recent'?'Recent sightings':'Seasonal records');}}
 await Promise.all([load('weather',()=>weather(location)),load('recent',()=>observations(location,true),'recentCoverage'),load('observations',()=>observations(location),'coverage')]);
 state.offline=failures.length>0;photoRequests.clear();save();render();$('status').textContent=failures.length?`${failures.join(', ')} unavailable. Saved data keeps its original timestamp; refresh online.`:'Report updated. Match these leads to the trees and moisture in your wood.';$('status').className=failures.length?'status error':'status';busy=false;$('refresh').disabled=false;$('locate').disabled=false;fillPhotos();return {location:state.location,weatherAvailable:!!state.weather,localRecordsAvailable:state.observations!==null};
}
for(const id of ['habitat','view'])$(id).addEventListener('change',()=>{visibleLimit=12;render();fillPhotos();});$('species-search').addEventListener('input',()=>{visibleLimit=12;render();fillPhotos();});$('show-more').addEventListener('click',()=>{visibleLimit+=12;render();fillPhotos();});$('refresh').addEventListener('click',()=>refresh());$('species-grid').addEventListener('click',e=>{const button=e.target.closest('[data-details]');if(button)showDetails(button.dataset.details);});
for(const b of ['guide-button','sources-button'])$(b).addEventListener('click',()=>$('method-dialog').showModal());document.querySelectorAll('.dialog-close').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('locate').addEventListener('click',()=>{if(!navigator.geolocation){$('status').textContent='This browser does not support location access. Search a town instead.';return;}if(busy)return;$('locate').disabled=true;$('status').textContent='Waiting for your location permission…';navigator.geolocation.getCurrentPosition(pos=>{const {latitude:lat,longitude:lng}=pos.coords;$('locate').disabled=false;if(lat<49.8||lat>61||lng<-9||lng>2){$('status').textContent='This version uses a UK species guide. Choose a UK location to continue.';return;}refresh({name:'Your location · UK guide',lat,lng});},()=>{$('locate').disabled=false;$('status').textContent='Location unavailable or permission declined. Search a nearby UK town instead.';},{enableHighAccuracy:false,timeout:15000,maximumAge:300000});});
let searchSeq=0;$('location-form').addEventListener('submit',async e=>{e.preventDefault();const token=++searchSeq;const name=$('place').value.trim();if(name.length<2)return;$('places').textContent='Searching UK places…';try{const q=new URLSearchParams({name,count:10,language:'en',format:'json',countryCode:'GB'});const data=await json(`https://geocoding-api.open-meteo.com/v1/search?${q}`);if(token!==searchSeq)return;const list=(data.results||[]).filter(x=>x.country_code==='GB');$('places').replaceChildren();if(!list.length){$('places').textContent='No UK town found. Try a nearby larger town.';return;}for(const p of list.slice(0,5)){const b=document.createElement('button');b.type='button';b.textContent=`${p.name}, ${p.admin2||p.admin1||'UK'}`;b.addEventListener('click',()=>{if(busy)return;$('places').replaceChildren();$('place').value=p.name;refresh({name:b.textContent,lat:p.latitude,lng:p.longitude});});$('places').append(b);}}catch{$('places').textContent='Place search unavailable. Try again when online, or use your location.';}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install').hidden=false;});$('install').addEventListener('click',async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('install').hidden=true;}});
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'check_mushroom_conditions',title:'Check mushroom scouting conditions',description:'Set a UK scouting location and refresh weather and historical nearby sightings in the visible report.',inputSchema:{type:'object',properties:{latitude:{type:'number',minimum:49.8,maximum:61},longitude:{type:'number',minimum:-9,maximum:2}},required:['latitude','longitude'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async input=>{if(!input||!number(input.latitude)||!number(input.longitude)||input.latitude<49.8||input.latitude>61||input.longitude<-9||input.longitude>2)throw new Error('Provide valid coordinates within the UK guide area.');if(busy)throw new Error('A report is already loading.');return await refresh({name:'Selected location · UK guide',lat:input.latitude,lng:input.longitude});}})).catch(()=>{});}catch{}}
render();refresh();
